import {icon} from '../../shared/ui.js';
export function backupSettings(){return `<section class="panel"><h2>Salvar e levar com você</h2><p>Os dados ficam neste navegador e perfil. Exporte um backup para levar a campanha a outro dispositivo ou endereço.</p><div class="button-row"><button class="primary" data-action="backup">↓ Exportar backup completo</button><button data-action="import">↑ Importar backup</button></div><p class="muted">JSON com campanhas, imagens, hierarquia e posições. A importação substitui o arquivo atual após validação.</p><button data-action="persistent">Solicitar armazenamento persistente</button><button class="text-button" data-action="restore">Restaurar gravação anterior</button><p id="storage-info" class="muted"></p></section><section class="panel linux-panel"><div>${icon('settings')}<h2>No seu Linux</h2><p>Extraia o projeto e execute <code>python3 serve.py</code>. Abra <code>http://127.0.0.1:8080</code> e importe seu backup.</p></div><a class="button" href="./caldris-linux.zip" download>↓ Código + imagens + guia Linux</a></section>`;}
